def network_address(ip, prefix):
    a, b, c, d = ip.split(".")
    n = (int(a) << 24) | (int(b) << 16) | (int(c) << 8) | int(d)
    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
    net = n & mask
    return ".".join(str((net >> shift) & 0xFF) for shift in (24, 16, 8, 0))

def parse_pairs(text):
    result = {}
    for segment in text.split(";"):
        key, sep, value = segment.partition("=")
        if sep:
            result[key.strip()] = value.strip()
    return result

def table(rows):
    lines = []
    for host, rtt in rows:
        lines.append(f"{host:<8}{rtt:>8.1f} ms")
    return "\n".join(lines)

def normalize_mac(text):
    clean = text.lower().translate(str.maketrans("", "", ":-."))
    if len(clean) != 12 or not all(c in "0123456789abcdef" for c in clean):
        return None
    return ":".join(clean[i:i + 2] for i in range(0, 12, 2))
